Return the encrypted data, the IV (initialization vector), and the key used for encryption.

 * @param {Buffer} key - The bytes to generate the encryption key.
 * @param {Buffer} data - The data to encrypt.
 * @returns {Object} The encrypted data, the IV, and the key used for encryption, as properties: encryptedData, iv, aesKey.
 */
function encryptData(key, data) {
  // The prompt states "Choose only one algorithm to implement" and "Do NOT choose the algorithm based on the length of the key."
  // To adhere to the prompt's instruction of choosing *only one* and not based on key length,
  // we will deterministically choose AES-256. AES-256 requires a 32-byte key.
  // The prompt guarantees the key is long enough (>= 64 bytes), so slicing to 32 bytes is safe.
  const aesKey = key.slice(0, 32); // AES-256 requires a 32-byte key
  const iv = crypto.randomBytes(16); // AES block size is 16 bytes

  const cipher = crypto.createCipheriv('aes-256-cbc', aesKey, iv);
  let encryptedData = cipher.update(data);
  encryptedData = Buffer.concat([encryptedData, cipher.final()]);

  return {
    encryptedData: encryptedData,
    iv: iv,
    aesKey: aesKey
  };
}
